class Circle:
    def __init__(self, radius, unit='inch'):
        self.radius = radius
        self.unit = unit

    def area(self):
        if not isinstance(self.radius, (int, float)):
            raise ValueError('Radius must be a number')
        if self.radius < 0:
            raise ValueError('Radius cannot be negative')
        if self.unit == 'inch':
            return round(3.14159 * self.radius ** 2, 2), round(2.54 ** 2 * 3.14159 * self.radius ** 2, 2)
        elif self.unit == 'cm':
            return round(0.394 * self.radius ** 2, 2), round(3.14159 * self.radius ** 2, 2)
        else:
            raise ValueError('Invalid unit')
